entries[148270] = { ["name"] = "Glyph of the Unbound Elemental", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nYour Water Elemental is replaced by an Unbound Water Elemental." }
entries[148271] = { ["name"] = "Glyph of Evaporation", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nReduces the size of your Water Elemental by 40%." }
entries[148272] = { ["name"] = "Glyph of Condensation", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the size of your Water Elemental by 40%." }
entries[148273] = { ["name"] = "Glyph of the Exorcist", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nExorcism will now appear to remove the evil from its target." }
entries[148274] = { ["name"] = "Glyph of Pillar of Light", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nCritical heals on other players display a small pillar of light at their location briefly." }
entries[148275] = { ["name"] = "Glyph of Angels", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nYour heal spells momentarily grant you angelic wings. (100ms cooldown)" }
entries[148276] = { ["name"] = "Glyph of the Sha", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nTransforms your Shadowfiend and Mindbender into a Sha Beast." }
entries[148277] = { ["name"] = "Glyph of Shifted Appearances", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nVoid Shift causes you and your target to exchange appearances for several seconds.\n\nDoes not affect mounted players." }
entries[148278] = { ["name"] = "Glyph of Inspired Hymns", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nWhile channeling Hymns, a spirit appears above you." }
entries[148279] = { ["name"] = "Glyph of Headhunting", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Rogue\n25\nUse: Permanently teaches you this glyph.\n\nYour Throw and Deadly Throw abilities will now throw axes regardless of your currently equipped weapon." }
entries[148280] = { ["name"] = "Glyph of Improved Distraction", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Rogue\n25\nUse: Permanently teaches you this glyph.\n\nDistract now summons a decoy at the target location." }
entries[148281] = { ["name"] = "Glyph of Spirit Raptors", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nYour Spirit Wolves are replaced with Spirit Raptors." }
entries[148282] = { ["name"] = "Glyph of Lingering Ancestors", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nResurrecting someone with Ancestral Spirit causes a ghostly ancestor to follow them around for a short time." }
entries[148283] = { ["name"] = "Glyph of Spirit Wolf", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nGhost Wolf can be now be used while you are a ghost." }
entries[148284] = { ["name"] = "Glyph of Flaming Serpent", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nYour Searing Totem now resembles Vol'jin's Serpent Ward." }
entries[148285] = { ["name"] = "Glyph of the Compy", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nYour Hex now transforms enemies into a Compy." }
entries[148286] = { ["name"] = "Glyph of Elemental Familiars", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nSummons a random Fire, Water, or Nature familiar. Familiars of different types have a tendency to fight each other." }
entries[148287] = { ["name"] = "Glyph of Astral Fixation", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nAstral Recall now takes you to your capital's Earthshrine." }
entries[148288] = { ["name"] = "Glyph of Rain of Frogs", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nYou summon a rain storm of frogs at your targeted location." }
entries[148289] = { ["name"] = "Glyph of the Raging Whirlwind", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Warrior\n25\nUse: Permanently teaches you this glyph.\n\nWhirlwind gives you 15 rage over 6 sec, but for that time you no longer generate rage from autoattacks." }
entries[148290] = { ["name"] = "Glyph of the Subtle Defender", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Warrior\n25\nUse: Permanently teaches you this glyph.\n\nRemoves the threat generation bonus from Defensive Stance." }
entries[148291] = { ["name"] = "Glyph of the Watchful Eye", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Warrior\n25\nUse: Permanently teaches you this glyph.\n\nIntervene will now target the party or raid member with the lowest health within 25 yards." }
entries[148292] = { ["name"] = "Glyph of the Weaponmaster", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Warrior\n25\nUse: Permanently teaches you this glyph.\n\nYour Shout abilities cause the appearance of your weapon to change to that of a random weapon from your primary bag for 10 min." }
